+        ([Description("Title or key point to save")] string title,
+         [Description("Detailed content of the note")] string content) =>
+        {
+            notes.Add(title, content);
+            return $"Note saved: {title}";
+        },
+        "save_note",
+        "Saves a research note with a title and content for later summarization."),
+    AIFunctionFactory.Create(
+        () => notes.GetAllFormatted(),
+        "get_notes",
+        "Retrieves all saved research notes to review or summarize findings."),
+]);
+
+// Create the agent with Microsoft Agent Framework
+var agent = new ChatClientAgent(chatClient, "ResearchAgent")
+{
+    Instructions = """
+        You are a research agent. Your job is to research a topic thoroughly by:
+        1. Searching the web for relevant information using the web_search tool.
+        2. Saving key findings as notes using the save_note tool.
+        3. After gathering enough information (at least 3-5 searches), retrieve your notes
+           with get_notes and provide a comprehensive summary.
+
+        Be thorough but focused. Search for different aspects of the topic.
+        Always save important findings before summarizing.
+        """,
+    Tools = tools,
+};
+
+Console.WriteLine("=== Research Agent ===");
+Console.WriteLine("Enter a topic to research (or 'quit' to exit):");
+Console.Write("> ");
+
+while (Console.ReadLine() is { } input && !input.Equals("quit", StringComparison.OrdinalIgnoreCase))
+{
+    if (string.IsNullOrWhiteSpace(input))
+    {
+        Console.Write("> ");
+        continue;
+    }
+
+    notes.Clear();
+    Console.WriteLine($"\nResearching: {input}\n");
+
+    var messages = new List<ChatMessage>
+    {
+        new(ChatRole.User, $"Research the following topic and provide a summary: {input}"),
+    };
+
+    var options = new AgentInvokeOptions
+    {
+        MaximumIterations = 10,
+    };
+
+    await foreach (var response in agent.InvokeStreamingAsync(messages, options))
+    {
+        if (response.Role == ChatRole.Assistant && !string.IsNullOrEmpty(response.Text))
+        {
+            Console.Write(response.Text);
+        }
+    }
+
+    Console.WriteLine("\n");
+    Console.Write("> ");
+}
+
+Console.WriteLine("Goodbye!");
+
+// --- Tool implementations ---
+
+/// <summary>Simulates web search results for demonstration purposes.</summary>
+static class WebSearchTool
+{
+    private static readonly HttpClient Http = new();
+
+    public static async Task<string> SearchAsync(string query)
+    {
+        // In production, replace with a real search API (Bing, Google, Tavily, etc.)
+        // This implementation demonstrates the tool contract.
+        Console.WriteLine($"  [Searching: {query}]");
+
+        try
+        {
+            // Use a simple web request as a demonstration
+            var encoded = Uri.EscapeDataString(query);
+            var url = $"https://en.wikipedia.org/w/api.php?action=query&list=search&srsearch={encoded}&format=json&srlimit=3&utf8=1";
+            var response = await Http.GetStringAsync(url);
+            return response.Length > 2000 ? response[..2000] : response;
+        }
+        catch (Exception ex)
+        {
+            return $"Search unavailable: {ex.Message}. Provide your best knowledge on: {query}";
+        }
+    }
+}
+
+/// <summary>Thread-safe note storage for the research agent.</summary>
+sealed class ResearchNotes
+{
+    private readonly List<(string Title, string Content)> _notes = [];
+
+    public void Add(string title, string content) => _notes.Add((title, content));
+
+    public void Clear() => _notes.Clear();
+
+    public string GetAllFormatted()
+    {
+        if (_notes.Count == 0)
+            return "No notes saved yet.";
+
+        return string.Join("\n\n", _notes.Select((n, i) =>
+            $"[{i + 1}] {n.Title}\n{n.Content}"));
+    }
+}

